document.querySelector(".theme-toggle")?.addEventListener("click",()=>{const e=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=e,localStorage.setItem("theme",e)}),document.querySelectorAll(".copy").forEach(e=>{e.addEventListener("click",async()=>{const t=e.dataset.copyTarget&&document.getElementById(e.dataset.copyTarget),n=e.dataset.copy||t&&t.textContent.trim();if(!n)return;await navigator.clipboard.writeText(n);const s=e.textContent;e.textContent="Copied",e.classList.add("is-done"),setTimeout(()=>{e.textContent=s,e.classList.remove("is-done")},1600)})})